{"apiVersion": "v1", "kind": "ConfigMap", "metadata": {"name": "nono-agent-profiles"}, "data": {"agent.json": "{
  "meta": {
    "name": "agent",
    "description": "Payments SRE agent: scoped LLM egress plus a query-only LogCLI child with exact argv and L7 policy"
  },
  "workdir": { "access": "readwrite" },
  "filesystem": {
    "allow": ["/workspace"],
    "read": ["/opt/agent"]
  },
  "network": {
    "credentials": ["llm"],
    "allow_domain": [
      { "domain": "api.openai.com", "endpoints": [ { "method": "POST", "path": "/v1/chat/completions" } ] }
    ],
    "custom_credentials": {
      "llm": {
        "upstream": "https://api.openai.com",
        "credential_key": "env://OPENAI_API_KEY",
        "env_var": "OPENAI_API_KEY",
        "inject_header": "Authorization",
        "credential_format": "Bearer {}",
        "endpoint_rules": [ { "method": "POST", "path": "/v1/chat/completions" } ]
      }
    }
  },
  "command_policies": {
    "credentials": {
      "loki": {
        "type": "proxy",
        "upstream": "https://nono-demo-loki:3100",
        "credential_key": "file:///etc/nono/loki-credential/token",
        "env_var": "LOKI_BEARER_TOKEN",
        "base_url_env_var": "LOKI_ADDR",
        "inject_header": "Authorization",
        "credential_format": "Bearer {}",
        "tls_ca": "/etc/nono/loki-tls/ca.crt"
      }
    },
    "commands": {
      "logcli": {
        "executable": "/usr/local/bin/logcli",
        "from": {
          "session": {
            "sandbox": {
              "network": {
                "allow_domain": ["nono-demo-loki"]
              },
              "credentials": [
                {
                  "name": "loki",
                  "endpoint_policy": {
                    "default": "deny",
                    "allow": [
                      { "method": "GET", "path": "/loki/api/v1/query_range" }
                    ]
                  }
                }
              ],
              "environment": {
                "allow_vars": ["PATH", "HOME", "LANG", "LC_*", "TZ"]
              },
              "stdio": {
                "stdout": { "max_bytes": 65536, "on_limit": "truncate" },
                "stderr": { "max_bytes": 16384, "on_limit": "terminate" }
              }
            },
            "invocation_policy": {
              "default": "deny",
              "deny": [
                {
                  "argv": { "prefix": ["delete"] },
                  "reason": "the agent may query incident logs but may not manage Loki deletion requests"
                }
              ],
              "allow": [
                {
                  "argv": {
                    "exact": [
                      "--quiet",
                      "--output=raw",
                      "query",
                      "--since=15m",
                      "--limit=10",
                      "{service=\"payments\"} |= \"p99 latency\""
                    ]
                  }
                },
                {
                  "argv": { "exact": ["--quiet", "labels"] }
                }
              ]
            }
          }
        }
      }
    }
  }
}
"}}

{"kind": "ConfigMap", "apiVersion": "v1", "metadata": {"name": "nginx-config"}, "data": {"nginx.conf": "user www-data;
worker_processes auto;
error_log /tmp/error.log;
pid /tmp/nginx.pid;


events {
    worker_connections 1024;
}

http {
    include /etc/nginx/conf.d/*.conf;

    upstream pypi {
        server pypi-server.test-pypiserver.svc.cluster.local:8080;
    }

    server {
        listen 8081 default_server;
        server_name localhost;

        # Redirect HTTP traffic to HTTPS
        return 301 https://$host$request_uri;
    }

    server {
        listen 8443 ssl;
        server_name localhost;

        ssl_certificate /etc/nginx/ssl/server.crt;
        ssl_certificate_key /etc/nginx/ssl/private.key;
        ssl_protocols       TLSv1 TLSv1.1 TLSv1.2;
        ssl_ciphers         HIGH:!aNULL:!MD5;


        location / {
        proxy_set_header  Host $host:$server_port;
        proxy_set_header  X-Forwarded-Proto $scheme;
        proxy_set_header  X-Real-IP $remote_addr;
        proxy_temp_path   /tmp/proxy_temp;
        proxy_set_header Connection "";
        proxy_pass        http://pypi;
      }
    }
}
